state.server:
#include "cold-setup.h"

_Static_assert(sizeof(struct npu_cold_packet) == NPU_COLD_SIZE, "cold wire changed");
_Static_assert(sizeof(struct npu_cold_setup) == 48, "cold owner changed");

static uint32_t load(const uint32_t *word)
{
    return __atomic_load_n(word, __ATOMIC_ACQUIRE);
}

static int held(const struct npu_admission *a, const struct npu_barrier *b,
                const struct npu_bootstrap *boot, uint32_t active)
{
    uint32_t i;

    if (a->closed != 1 || a->active != active || a->fault ||
        !(a->nonce_lo || a->nonce_hi) || load(&b->request) != 1 ||
        load(&b->fault) || load(&b->prepared) || load(&b->released) || load(&b->armed) ||
        boot->magic != NPU_BOOTSTRAP_MAGIC || boot->failed || boot->inflight ||
        boot->step != NPU_BOOTSTRAP_STEPS || boot->retained_mask != 0x1e)
        return 0;
    for (i = 0; i < NPU_BARRIER_WORKERS; i++)
        if (load(&b->parked[i]) != 1 || load(&b->ready[i]))
            return 0;
    for (i = 0; i < NPU_BARRIER_DOMAINS; i++)
        if (load(&b->drained[i]))
            return 0;
    for (i = 0; i < NPU_ADMISSION_IRQ_WORDS; i++)
        if (a->deferred[i])
            return 0;
    return 1;
}

static enum npu_cold_status fail(struct npu_cold_setup *s,
    struct npu_admission *a, struct npu_barrier *b, enum npu_cold_status error)
{
    s->failed = 1;
    npu_admission_fail(a, b);
    return error;
}

static uint32_t command_bit(const struct npu_bootstrap_packet *p)
{
    if (p->header == 0x10 && p->api == 14 && p->value == 2)
        return NPU_COLD_PORT;
    if (p->header == 0x10 && p->api == 1 && p->value && p->value <= 1536)
        return NPU_COLD_RX0;
    if (p->header == 0x12 && p->api == 1 && p->value && p->value <= 1024)
        return NPU_COLD_RX2;
    return 0;
}

enum npu_cold_status npu_cold_setup_begin(struct npu_cold_setup *s,
    struct npu_control_v2_session *session, struct npu_admission *a,
    struct npu_barrier *b, const struct npu_bootstrap *boot,
    const struct npu_cold_packet *packet, uint32_t bytes)
{
    struct npu_cold_packet p;
    uint32_t i, bit;

    if (!packet || bytes != sizeof(p))
        return NPU_COLD_BAD_MESSAGE;
    npu_cold_packet_copy(&p, packet);
    if (p.header != NPU_CONTROL_HEADER || p.api != NPU_COLD_API ||
        p.magic != NPU_COLD_REQUEST || p.version != NPU_COLD_VERSION ||
        p.bytes != sizeof(p) || !p.sequence || p.status)
        return NPU_COLD_BAD_MESSAGE;
    for (i = 0; i < 5; i++)
        if (p.reserved[i])
            return NPU_COLD_BAD_MESSAGE;
    if (!(session->boot_lo || session->boot_hi) ||
        p.boot_lo != session->boot_lo || p.boot_hi != session->boot_hi)
        return NPU_COLD_BAD_BOOT;
    if (!(session->nonce_lo || session->nonce_hi) ||
        p.nonce_lo != session->nonce_lo || p.nonce_hi != session->nonce_hi ||
        a->nonce_lo != session->nonce_lo || a->nonce_hi != session->nonce_hi)
        return NPU_COLD_BAD_SESSION;
    if (p.sequence <= session->last_sequence)
        return NPU_COLD_REPLAY;
    /* Reserve before platform/command checks: abandonment never enables replay. */
    session->last_sequence = p.sequence;
    if (s->failed || s->inflight || (s->completed & ~7u) ||
        p.epoch != 1 || !held(a, b, boot, 0))
        return fail(s, a, b, NPU_COLD_BAD_STATE);
    bit = command_bit(&p.command);
    if (!bit && !(p.command.header == 0x30 && p.command.api == 10 && !p.command.value))
        return fail(s, a, b, NPU_COLD_UNSUPPORTED);
    if ((bit && (s->completed & bit)) ||
        (bit == NPU_COLD_PORT && s->completed) ||
        (bit == NPU_COLD_RX0 && s->completed != NPU_COLD_PORT) ||
        (bit == NPU_COLD_RX2 && s->completed != (NPU_COLD_PORT | NPU_COLD_RX0)))
        return fail(s, a, b, NPU_COLD_BAD_STATE);
    s->command = p.command;
    s->sequence = p.sequence;
    s->boot_lo = p.boot_lo;
    s->boot_hi = p.boot_hi;
    s->nonce_lo = p.nonce_lo;
    s->nonce_hi = p.nonce_hi;
    s->prior_completed = s->completed;
    s->inflight = a->active = 1;
    return NPU_COLD_OK;
}

enum npu_cold_status npu_cold_setup_finish(struct npu_cold_setup *s,
    struct npu_control_v2_session *session, struct npu_admission *a,
    struct npu_barrier *b, const struct npu_bootstrap *boot,
    uint32_t result, const struct npu_bootstrap_packet *reply)
{
    uint32_t bit = command_bit(&s->command);

    if (s->failed || s->inflight != 1 || !held(a, b, boot, 1) ||
        session->last_sequence != s->sequence ||
        session->boot_lo != s->boot_lo || session->boot_hi != s->boot_hi ||
        session->nonce_lo != s->nonce_lo || session->nonce_hi != s->nonce_hi ||
        a->nonce_lo != s->nonce_lo || a->nonce_hi != s->nonce_hi ||
        s->completed != s->prior_completed ||
        !reply || result != 1 || reply->header != s->command.header ||
        reply->api != s->command.api ||
        reply->value != (bit ? s->command.value : 0x457u))
        return fail(s, a, b, NPU_COLD_CALLBACK_FAILED);
    s->completed |= bit;
    s->inflight = a->active = 0;
    return NPU_COLD_OK;
}

state.client:
#include "cold-setup.h"

static uint32_t read_word(const unsigned char *p, uint32_t i)
{
    p += i * 4;
    return (uint32_t)p[0] | (uint32_t)p[1] << 8 |
           (uint32_t)p[2] << 16 | (uint32_t)p[3] << 24;
}

static void write_word(unsigned char *p, uint32_t i, uint32_t value)
{
    p += i * 4;
    p[0] = (unsigned char)value;
    p[1] = (unsigned char)(value >> 8);
    p[2] = (unsigned char)(value >> 16);
    p[3] = (unsigned char)(value >> 24);
}

static enum npu_client_result fail(struct npu_control_v2_client *s,
                                   enum npu_client_v2_error error)
{
    if (s->base.phase != NPU_CLIENT_FAILED) {
        s->error = error;
        npu_client_v2_abort(s);
    }
    return NPU_CLIENT_REJECTED;
}

uint32_t npu_cold_client_request(struct npu_control_v2_client *s,
    void *packet, uint32_t bytes, const struct npu_bootstrap_packet *p)
{
    uint32_t i;

    if (s->base.phase == NPU_CLIENT_FAILED || s->base.pending)
        return 0;
    if (!packet || bytes != NPU_COLD_SIZE || !p ||
        s->base.phase != NPU_CLIENT_PARKED || s->base.epoch != 1 ||
        s->base.released || s->base.armed || s->base.ready_mask || s->base.drain_mask ||
        s->base.parked_mask != 0xff || !(s->boot_lo || s->boot_hi) ||
        !(s->base.nonce_lo || s->base.nonce_hi) || s->base.serial == UINT32_MAX) {
        fail(s, NPU_CLIENT_V2_ARGUMENT);
        return 0;
    }
    for (i = 0; i < NPU_COLD_SIZE / 4; i++)
        write_word(packet, i, 0);
    write_word(packet, 0, NPU_CONTROL_HEADER);
    write_word(packet, 1, NPU_COLD_API);
    write_word(packet, 2, NPU_COLD_REQUEST);
    write_word(packet, 3, NPU_COLD_VERSION);
    write_word(packet, 4, NPU_COLD_SIZE);
    write_word(packet, 5, 1);
    write_word(packet, 6, s->base.serial + 1);
    write_word(packet, 7, s->base.nonce_lo);
    write_word(packet, 8, s->base.nonce_hi);
    write_word(packet, 9, s->boot_lo);
    write_word(packet, 10, s->boot_hi);
    write_word(packet, 11, p->header);
    write_word(packet, 12, p->api);
    write_word(packet, 13, p->value);
    s->base.operation = NPU_COLD_PENDING_OPERATION;
    s->base.pending = ++s->base.serial;
    return s->base.pending;
}

enum npu_client_result npu_cold_client_complete(struct npu_control_v2_client *s,
    uint32_t ticket, int error, const void *packet, uint32_t bytes,
    const struct npu_bootstrap_packet *command, uint32_t *value)
{
    uint32_t i, result;

    if (!ticket || ticket != s->base.pending || s->base.phase == NPU_CLIENT_FAILED)
        return NPU_CLIENT_IGNORED;
    if (error)
        return fail(s, NPU_CLIENT_V2_ENVELOPE);
    if (!packet || bytes != NPU_COLD_SIZE || !command || !value ||
        s->base.phase != NPU_CLIENT_PARKED || s->base.operation != NPU_COLD_PENDING_OPERATION)
        return fail(s, NPU_CLIENT_V2_ARGUMENT);
    if (read_word(packet, 0) != NPU_CONTROL_HEADER || read_word(packet, 1) != NPU_COLD_API ||
        read_word(packet, 2) != NPU_COLD_REPLY || read_word(packet, 3) != NPU_COLD_VERSION ||
        read_word(packet, 4) != NPU_COLD_SIZE || read_word(packet, 5) != 1 ||
        read_word(packet, 6) != ticket || read_word(packet, 7) != s->base.nonce_lo ||
        read_word(packet, 8) != s->base.nonce_hi || read_word(packet, 9) != s->boot_lo ||
        read_word(packet, 10) != s->boot_hi || read_word(packet, 11) != command->header ||
        read_word(packet, 12) != command->api || read_word(packet, 14) != NPU_COLD_OK)
        return fail(s, NPU_CLIENT_V2_ENVELOPE);
    for (i = 15; i < 20; i++)
        if (read_word(packet, i))
            return fail(s, NPU_CLIENT_V2_ENVELOPE);
    result = read_word(packet, 13);
    if (result != (command->header == 0x30 && command->api == 10 ? 0x457u : command->value))
        return fail(s, NPU_CLIENT_V2_ENVELOPE);
    s->base.pending = 0;
    *value = result;
    return NPU_CLIENT_ACCEPTED;
}

state.linux_exchange:
int npu_linux_control_cold_exchange(struct npu_linux_control *control,
				    const struct npu_bootstrap_packet *command,
				    u32 *value)
{
	struct npu_bootstrap_packet snapshot;
	struct npu_cold_packet packet;
	enum npu_client_result result;
	u32 ticket;
	int error;

	if (!control || !control->initialized || !command || !value)
		return -EINVAL;
	mutex_lock(&control->mutex);
	if (control->error) {
		error = control->error;
		goto unlock;
	}
	if (control->closed || !control->provider) {
		error = hold(control, -ESHUTDOWN);
		goto unlock;
	}
	snapshot = *command;
	ticket = npu_cold_client_request(&control->client, &packet,
					 sizeof(packet), &snapshot);
	if (!ticket) {
		error = hold(control, -EPROTO);
		goto unlock;
	}
	error = airoha_npu_wlan_control(control->provider, &packet, sizeof(packet));
	result = npu_cold_client_complete(&control->client, ticket, error,
					  &packet, sizeof(packet), &snapshot, value);
	if (error || result != NPU_CLIENT_ACCEPTED)
		error = hold(control, error < 0 ? error : error ? -EIO : -EPROTO);
unlock:
	mutex_unlock(&control->mutex);
	return error;
}

provider.airoha_npu_wlan_cold_command:
static int airoha_npu_wlan_cold_command(struct airoha_npu *npu, u32 header,
					u32 api, void *data, int len)
{
	struct airoha_npu_priv *priv = container_of(npu, struct airoha_npu_priv, npu);
	struct npu_bootstrap_packet command = { .header = header, .api = api };
	u32 value;
	int err;

	if (!data || len != sizeof(value))
		return -EINVAL;
	if (header != 0x30)
		command.value = get_unaligned_le32(data);
	mutex_lock(&priv->wlan_session_lock);
	if (priv->wlan_session_error) {
		err = priv->wlan_session_error;
		goto unlock;
	}
	if (!priv->wlan_session_attempted || !priv->wlan_control.initialized) {
		err = -EINVAL;
		goto unlock;
	}
	err = npu_linux_control_cold_exchange(&priv->wlan_control, &command, &value);
	if (err) {
		priv->wlan_session_error = err;
		npu_linux_control_close(&priv->wlan_control);
	} else if (header == 0x30) {
		put_unaligned_le32(value, data);
	}
unlock:
	mutex_unlock(&priv->wlan_session_lock);
	return err;
}

provider.airoha_npu_wlan_msg_get_session:
static int airoha_npu_wlan_msg_get_session(struct airoha_npu *npu, int ifindex,
					   enum airoha_npu_wlan_get_cmd func_id,
					   void *data, int data_len, gfp_t gfp)
{
	struct airoha_npu_priv *priv = container_of(npu, struct airoha_npu_priv, npu);

	/* Probe's early version query precedes session publication and stays raw. */
	if (priv->checked_pair && READ_ONCE(priv->wlan_session_attempted) &&
	    ifindex == 0 && func_id == WLAN_FUNC_GET_WAIT_NPU_VERSION)
		return airoha_npu_wlan_cold_command(npu, 0x30, func_id, data, data_len);
	return airoha_npu_wlan_msg_get(npu, ifindex, func_id, data, data_len, gfp);
}

provider.airoha_npu_wlan_msg_send_session:
static int airoha_npu_wlan_msg_send_session(struct airoha_npu *npu, int ifindex,
					    enum airoha_npu_wlan_set_cmd func_id,
					    void *data, int data_len, gfp_t gfp)
{
	struct airoha_npu_priv *priv = container_of(npu, struct airoha_npu_priv, npu);

	if (priv->checked_pair &&
	    ((ifindex == 0 && func_id == WLAN_FUNC_SET_WAIT_PCIE_PORT_TYPE) ||
	     ((ifindex == 0 || ifindex == 2) && func_id == WLAN_FUNC_SET_WAIT_DESC)))
		return airoha_npu_wlan_cold_command(npu, 0x10 | ifindex, func_id,
						  data, data_len);
	return airoha_npu_wlan_msg_send(npu, ifindex, func_id, data, data_len, gfp);
}
